module med19 (
  input clk, input rst_n, input [7:0] x, output reg [15:0] y
);
  reg [7:0] window [0:18];
  integer i, j, k;
  reg [7:0] t;
  always @(posedge clk) begin
    if (!rst_n) begin
      for (i = 0; i < 19; i = i + 1) window[i] <= 8'd0;
      y <= 16'd0;
    end else begin
      window[0] <= x;
      for (i = 1; i < 19; i = i + 1) window[i] <= window[i-1];
      for (i = 0; i < 18; i = i + 1)
        for (j = i + 1; j < 19; j = j + 1)
          if (window[i] > window[j]) begin t <= window[i]; window[i] <= window[j]; window[j] <= t; end
      y <= {8'd0, window[9]};
    end
  end
endmodule

